'use client'

// Route Handlers are reached from Client Components: the relative URL
// '/api/users/profile' only resolves in the browser, and calling a Route Handler
// from a Server Component would cost an extra server request.
import { useEffect, useState } from 'react'

interface Profile {
  name: string
  email: string
}

export default function UserProfile() {
  const [profile, setProfile] = useState<Profile | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()

    fetch('/api/users/profile', { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`Request failed with status ${res.status}`)
        return res.json()
      })
      .then((data: Profile) => setProfile(data))
      .catch((err: unknown) => {
        if (err instanceof Error && err.name === 'AbortError') return
        setError(err instanceof Error ? err.message : 'Unknown error')
      })

    return () => controller.abort()
  }, [])

  if (error) {
    return <div>Could not load profile: {error}</div>
  }

  if (!profile) {
    return <div>Loading profile...</div>
  }

  return (
    <div>
      <h2>Profile</h2>
      <div>{profile.name}</div>
      <div>{profile.email}</div>
    </div>
  )
}

